options.css:
* { box-sizing: border-box; margin: 0; padding: 0; }
body { background: transparent; font-family: Georgia, serif; color: #cde; }

.wrap {
  background: #0a1628;
  border-radius: 10px;
  padding: 14px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

/* ── Location buttons ── */
.loc-btns { display: flex; gap: 8px; flex-wrap: wrap; }
.loc-btn {
  background: rgba(255,255,255,0.08);
  color: #7eb8ff;
  border: 1px solid rgba(30,144,255,0.3);
  border-radius: 20px;
  padding: 5px 14px;
  font-size: 12px;
  cursor: pointer;
  transition: all 0.2s;
  font-family: Georgia, serif;
}
.loc-btn.active { background: #1e90ff; color: #fff; border-color: #1e90ff; }
.loc-btn:hover  { background: rgba(30,144,255,0.2); }

/* ── Date row ── */
.date-row {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}
.nav-btn {
  background: rgba(255,255,255,0.07);
  color: #7eb8ff;
  border: 1px solid rgba(30,144,255,0.3);
  border-radius: 8px;
  padding: 4px 12px;
  font-size: 14px;
  cursor: pointer;
  transition: all 0.2s;
  font-family: Georgia, serif;
}
.nav-btn:hover  { background: rgba(30,144,255,0.2); border-color: #1e90ff; color: #fff; }
.today-btn      { font-size: 11px; padding: 4px 10px; color: #48dbfb; border-color: rgba(72,219,251,0.4); }
.today-btn:hover{ background: rgba(72,219,251,0.15); border-color: #48dbfb; }
#datePicker {
  background: #0d1f3c;
  border: 1px solid rgba(30,144,255,0.4);
  border-radius: 8px;
  color: #7eb8ff;
  font-size: 13px;
  padding: 4px 10px;
  cursor: pointer;
  outline: none;
  font-family: Georgia, serif;
}
#datePicker::-webkit-calendar-picker-indicator {
  filter: invert(0.6) sepia(1) saturate(5) hue-rotate(175deg);
  cursor: pointer;
}
.date-display { font-size: 11px; color: #3d5a7a; margin-left: 4px; }

/* ── Weather strip ── */
.wx-strip {
  background: rgba(30,144,255,0.06);
  border: 1px solid rgba(30,144,255,0.12);
  border-radius: 8px;
  padding: 8px 12px;
  display: flex;
  flex-direction: column;
  gap: 5px;
}
.wx-strip-main {
  display: flex;
  align-items: baseline;
  gap: 10px;
  flex-wrap: wrap;
}
.wx-big-temp {
  font-size: 28px;
  font-weight: bold;
  color: #fff;
  line-height: 1;
}
.wx-feels { font-size: 12px; color: #5a7fa0; }
.wx-desc  { font-size: 13px; color: #b0c8e8; }
.wx-strip-stats {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  align-items: center;
}
.wx-stat      { font-size: 11px; color: #7eb8ff; white-space: nowrap; }
.trend-stat   { font-size: 14px; font-weight: bold; }

/* ── Barometer bar ── */
.baro-row {
  display: flex;
  align-items: center;
  gap: 6px;
}
.baro-label-left, .baro-label-right {
  font-size: 9px;
  color: #3d5a7a;
  white-space: nowrap;
}
.baro-track {
  flex: 1;
  position: relative;
  height: 6px;
  background: rgba(255,255,255,0.07);
  border-radius: 3px;
  overflow: visible;
}
.baro-fill {
  height: 100%;
  border-radius: 3px;
  background: linear-gradient(90deg, #ff4757 0%, #ffd32a 35%, #2ed573 55%, #1e90ff 100%);
  transition: width 0.5s;
}
.baro-marker {
  position: absolute;
  top: -4px;
  width: 3px;
  height: 14px;
  background: #fff;
  border-radius: 2px;
  transform: translateX(-50%);
  transition: left 0.5s;
  box-shadow: 0 0 5px rgba(255,255,255,0.8);
}
.baro-hint {
  font-size: 10px;
  color: #ffd32a;
  white-space: nowrap;
  min-width: 140px;
}

/* ── Score bar ── */
.score-bar {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  min-height: 24px;
  padding: 2px 0;
  border-top: 1px solid rgba(255,255,255,0.05);
}
.score-pill {
  border-radius: 20px;
  padding: 3px 12px;
  font-size: 12px;
  font-weight: bold;
}
.score-stat { font-size: 11px; color: #5a7fa0; }

/* ── Chart ── */
.chart-wrap { position: relative; width: 100%; height: 220px; }

/* ── Fishing impact bar ── */
.impact-bar {
  font-size: 11px;
  color: #b0c8e8;
  line-height: 1.6;
  padding: 4px 0;
  border-top: 1px solid rgba(255,255,255,0.05);
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

/* ── Legend ── */
.legend {
  display: flex;
  gap: 14px;
  flex-wrap: wrap;
  font-size: 11px;
  color: #5a7fa0;
  align-items: center;
  border-top: 1px solid rgba(255,255,255,0.05);
  padding-top: 6px;
}
.ldot {
  width: 12px;
  height: 10px;
  border-radius: 2px;
  display: inline-block;
  margin-right: 3px;
  vertical-align: middle;
}
.msg { color: #5a7fa0; font-size: 12px; }
.err { color: #ff6b6b; font-size: 12px; }

options.onRender:
// ── Config ────────────────────────────────────────────────────────────────────
const PROM       = '/api/datasources/proxy/3';
const QUERY_HOST = window.location.hostname;
const QUERY_URL  = 'http://' + QUERY_HOST + ':9878/query';

let activeLoc  = 'freeport_tx';
let activeDate = new Date();

const LOCS = [
  { id:'freeport_tx',     label:'Freeport TX' },
  { id:'padre_island_tx', label:'N Padre Island TX' },
  { id:'pensacola_fl',    label:'Pensacola FL' },
  { id:'sargent_tx',      label:'Sargent TX' },
  { id:'matagorda_tx',    label:'Matagorda TX' },
];

// ── Date helpers ──────────────────────────────────────────────────────────────
function toDateStr(d) {
  return d.getFullYear().toString() +
    String(d.getMonth()+1).padStart(2,'0') +
    String(d.getDate()).padStart(2,'0');
}
function toInputVal(d) {
  return d.getFullYear() + '-' +
    String(d.getMonth()+1).padStart(2,'0') + '-' +
    String(d.getDate()).padStart(2,'0');
}
function isToday(d) {
  const t = new Date();
  return d.getFullYear()===t.getFullYear() && d.getMonth()===t.getMonth() && d.getDate()===t.getDate();
}
function offsetDate(d, days) {
  const nd = new Date(d); nd.setDate(nd.getDate()+days); return nd;
}

// ── Init ──────────────────────────────────────────────────────────────────────
function init() {
  const btnContainer = htmlNode.querySelector('#loc-btns');
  const picker       = htmlNode.querySelector('#datePicker');
  const btnPrev      = htmlNode.querySelector('#btn-prev');
  const btnNext      = htmlNode.querySelector('#btn-next');
  const btnToday     = htmlNode.querySelector('#btn-today');

  if (!btnContainer || !picker) { setTimeout(init, 100); return; }

  picker.value = toInputVal(activeDate);

  btnContainer.innerHTML = '';
  LOCS.forEach(loc => {
    const btn = document.createElement('button');
    btn.textContent = loc.label;
    btn.className   = 'loc-btn' + (loc.id === activeLoc ? ' active' : '');
    btn.id          = 'btn-' + loc.id;
    btn.addEventListener('click', () => setLoc(loc.id));
    btnContainer.appendChild(btn);
  });

  picker.addEventListener('change', () => {
    const parts = picker.value.split('-');
    activeDate = new Date(parseInt(parts[0]), parseInt(parts[1])-1, parseInt(parts[2]));
    loadAndDraw(activeLoc, activeDate);
  });
  btnPrev.addEventListener('click', () => {
    activeDate = offsetDate(activeDate, -1);
    picker.value = toInputVal(activeDate);
    loadAndDraw(activeLoc, activeDate);
  });
  btnNext.addEventListener('click', () => {
    activeDate = offsetDate(activeDate, 1);
    picker.value = toInputVal(activeDate);
    loadAndDraw(activeLoc, activeDate);
  });
  btnToday.addEventListener('click', () => {
    activeDate = new Date();
    picker.value = toInputVal(activeDate);
    loadAndDraw(activeLoc, activeDate);
  });

  loadAndDraw(activeLoc, activeDate);
}

function setLoc(loc) {
  activeLoc = loc;
  htmlNode.querySelectorAll('.loc-btn').forEach(b => b.classList.remove('active'));
  const btn = htmlNode.querySelector('#btn-'+loc);
  if (btn) btn.classList.add('active');
  loadAndDraw(loc, activeDate);
}

// ── Prometheus query ──────────────────────────────────────────────────────────
function pq(expr) {
  return new Promise((resolve) => {
    const xhr = new XMLHttpRequest();
    xhr.open('GET', PROM + '/api/v1/query?query=' + encodeURIComponent(expr), true);
    xhr.onload = () => {
      try { const d = JSON.parse(xhr.responseText); resolve(d.data ? d.data.result : []); }
      catch(e) { resolve([]); }
    };
    xhr.onerror = xhr.ontimeout = () => resolve([]);
    xhr.timeout = 10000;
    xhr.send();
  });
}

// ── On-demand date query ──────────────────────────────────────────────────────
function fetchDateData(loc, d) {
  return new Promise((resolve) => {
    const url = QUERY_URL + '?location=' + loc + '&date=' + toDateStr(d);
    const xhr = new XMLHttpRequest();
    xhr.open('GET', url, true);
    xhr.onload = () => {
      try { resolve(JSON.parse(xhr.responseText)); }
      catch(e) { resolve(null); }
    };
    xhr.onerror = xhr.ontimeout = () => resolve(null);
    xhr.timeout = 15000;
    xhr.send();
  });
}

// ── Helpers ───────────────────────────────────────────────────────────────────
function toLocalHr(unix) {
  if (!unix || unix === 0) return null;
  const d = new Date(parseFloat(unix) * 1000);
  return d.getHours() + d.getMinutes() / 60;
}
function fmtH(h) {
  if (h === null || h === undefined) return '--';
  const hr = Math.floor(h), mn = Math.round((h % 1) * 60);
  return (hr % 12 || 12) + ':' + (mn < 10 ? '0' : '') + mn + (hr < 12 ? 'am' : 'pm');
}
function fmtUnix(unix) { return unix ? fmtH(toLocalHr(unix)) : '--'; }
function getByPeriod(arr, p) {
  const m = arr.find(r => r.metric && r.metric.period === String(p));
  return m ? parseFloat(m.value[1]) : null;
}
function scalar(arr) {
  return arr && arr.length ? parseFloat(arr[0].value[1]) : null;
}

// ── Weather rendering ─────────────────────────────────────────────────────────
function renderWeather(loc) {
  // Only render weather for today — NWS is real-time only
  const wxEl   = id => htmlNode.querySelector(id);

  Promise.all([
    pq('fishing_weather_temp_f{location="'+loc+'"}'),
    pq('fishing_weather_feels_like_f{location="'+loc+'"}'),
    pq('fishing_weather_pressure_mb{location="'+loc+'"}'),
    pq('fishing_weather_pressure_trend{location="'+loc+'"}'),
    pq('fishing_weather_wind_speed_mph{location="'+loc+'"}'),
    pq('fishing_weather_wind_deg{location="'+loc+'"}'),
    pq('fishing_weather_precip_chance_pct{location="'+loc+'"}'),
    pq('fishing_weather_humidity_pct{location="'+loc+'"}'),
    pq('fishing_weather_cloud_cover_pct{location="'+loc+'"}'),
    pq('fishing_weather_visibility_miles{location="'+loc+'"}'),
    pq('fishing_weather{location="'+loc+'"}'),      // Info metric → labels
  ]).then(R => {
    const temp      = scalar(R[0]);
    const feels     = scalar(R[1]);
    const pressure  = scalar(R[2]);
    const trend     = scalar(R[3]);   // -1 / 0 / 1
    const windSpd   = scalar(R[4]);
    const windDeg   = scalar(R[5]);
    const precip    = scalar(R[6]);
    const humidity  = scalar(R[7]);
    const clouds    = scalar(R[8]);
    const vis       = scalar(R[9]);

    // Info metric comes back as a metric with labels, value always "1"
    let desc = '', trendStr = '→', windDir = '';
    if (R[10] && R[10].length) {
      const m = R[10][0].metric;
      desc     = m.description  || '';
      trendStr = m.pressure_trend || '→';
      windDir  = m.wind_dir     || '';
    }

    // Populate DOM
    const tempEl = wxEl('#wx-temp');
    if (tempEl) tempEl.textContent = temp !== null ? Math.round(temp) + '°F' : '--';

    const feelsEl = wxEl('#wx-feels');
    if (feelsEl) feelsEl.textContent = feels !== null ? 'Feels ' + Math.round(feels) + '°F' : '';

    const descEl = wxEl('#wx-desc');
    if (descEl) descEl.textContent = desc || 'N/A';

    const pressEl = wxEl('#wx-pressure');
    if (pressEl) pressEl.textContent = pressure !== null ? pressure.toFixed(1) + ' mb' : '-- mb';

    const trendEl = wxEl('#wx-trend');
    if (trendEl) {
      trendEl.textContent = trendStr;
      trendEl.style.color = trend > 0 ? '#2ed573' : trend < 0 ? '#ff4757' : '#ffd32a';
    }

    // Wind direction compass from degrees
    function degToCompass(deg) {
      if (deg === null) return 'N/A';
      const dirs = ['N','NNE','NE','ENE','E','ESE','SE','SSE','S','SSW','SW','WSW','W','WNW','NW','NNW'];
      return dirs[Math.round(deg / 22.5) % 16];
    }
    const windEl = wxEl('#wx-wind');
    if (windEl) windEl.textContent = windSpd !== null
      ? windSpd.toFixed(0) + ' mph ' + (windDir || degToCompass(windDeg))
      : '-- mph';

    const precipEl = wxEl('#wx-precip');
    if (precipEl) precipEl.textContent = '🌧️ ' + (precip !== null ? Math.round(precip) + '%' : '--%');

    const humEl = wxEl('#wx-humidity');
    if (humEl) humEl.textContent = '💧 ' + (humidity !== null ? Math.round(humidity) + '%' : '--%');

    const cloudEl = wxEl('#wx-clouds');
    if (cloudEl) cloudEl.textContent = '☁️ ' + (clouds !== null ? Math.round(clouds) + '%' : '--%');

    const visEl = wxEl('#wx-visibility');
    if (visEl) visEl.textContent = '👁️ ' + (vis !== null ? vis.toFixed(1) + ' mi' : '-- mi');

    // ── Barometer bar ─────────────────────────────────────────────────────────
    // Range: 980 mb (stormy) to 1050 mb (very high)
    if (pressure !== null) {
      const min = 980, max = 1050;
      const pct = Math.max(0, Math.min(100, ((pressure - min) / (max - min)) * 100));

      const fill   = wxEl('#baro-fill');
      const marker = wxEl('#baro-marker');
      const hint   = wxEl('#baro-hint');

      if (fill)   fill.style.width = pct + '%';
      if (marker) marker.style.left = pct + '%';

      if (hint) {
        let baroDesc = '';
        if (pressure < 1000)      baroDesc = '⛈️ Stormy — fish deeper';
        else if (pressure < 1010) baroDesc = '🌧️ Low pressure — slow bite';
        else if (pressure < 1020) baroDesc = '⛅ Normal — average bite';
        else if (pressure < 1030) baroDesc = '🌤️ High pressure — fish edges';
        else                      baroDesc = '☀️ Very high — tough topwater';

        const trendIcon = trend > 0 ? ' ↑ Rising' : trend < 0 ? ' ↓ Falling' : ' → Steady';
        hint.textContent = pressure.toFixed(1) + ' mb' + trendIcon + ' — ' + baroDesc;
      }
    }
  }).catch(e => {
    const descEl = htmlNode.querySelector('#wx-desc');
    if (descEl) descEl.textContent = 'Weather unavailable';
    console.warn('Weather fetch error:', e);
  });
}

function clearWeather() {
  const ids = ['#wx-temp','#wx-feels','#wx-desc','#wx-pressure','#wx-trend',
               '#wx-wind','#wx-precip','#wx-humidity','#wx-clouds','#wx-visibility'];
  ids.forEach(id => {
    const el = htmlNode.querySelector(id);
    if (el) el.textContent = id === '#wx-desc' ? 'Weather unavailable' : '--';
  });
  const hint = htmlNode.querySelector('#baro-hint');
  if (hint) hint.textContent = '';
  const fill = htmlNode.querySelector('#baro-fill');
  if (fill) fill.style.width = '0%';
}

function renderWeatherFromQuery(wx) {
  if (!wx || Object.keys(wx).length === 0) { clearWeather(); return; }
  const wxEl = id => htmlNode.querySelector(id);
  const temp     = wx.temp_f          != null ? wx.temp_f          : null;
  const pressure = wx.pressure_mb     != null ? wx.pressure_mb     : null;
  const windSpd  = wx.wind_speed_mph  != null ? wx.wind_speed_mph  : null;
  const windDeg  = wx.wind_deg        != null ? wx.wind_deg        : null;
  const precip   = wx.precip_chance   != null ? wx.precip_chance   : null;
  const humidity = wx.humidity        != null ? wx.humidity        : null;
  const clouds   = wx.cloud_cover     != null ? wx.cloud_cover     : null;
  const desc     = wx.description || '';

  const tempEl = wxEl('#wx-temp');
  if (tempEl) tempEl.textContent = temp !== null ? Math.round(temp) + '\u00b0F' : '--';

  const feelsEl = wxEl('#wx-feels');
  if (feelsEl) feelsEl.textContent = '';

  const descEl = wxEl('#wx-desc');
  if (descEl) descEl.textContent = desc || 'N/A';

  const pressEl = wxEl('#wx-pressure');
  if (pressEl) pressEl.textContent = pressure !== null ? pressure.toFixed(1) + ' mb' : '--';

  const trendEl = wxEl('#wx-trend');
  if (trendEl) { trendEl.textContent = '\u2192'; trendEl.style.color = '#ffd32a'; }

  function degToCompass(deg) {
    if (deg === null) return '';
    const dirs = ['N','NNE','NE','ENE','E','ESE','SE','SSE','S','SSW','SW','WSW','W','WNW','NW','NNW'];
    return dirs[Math.round(deg / 22.5) % 16];
  }
  const windEl = wxEl('#wx-wind');
  if (windEl) windEl.textContent = windSpd !== null
    ? windSpd.toFixed(0) + ' mph ' + degToCompass(windDeg)
    : '-- mph';

  const precipEl = wxEl('#wx-precip');
  if (precipEl) precipEl.textContent = '\ud83c\udf27\ufe0f ' + (precip !== null ? Math.round(precip) + '%' : '--%');

  const humEl = wxEl('#wx-humidity');
  if (humEl) humEl.textContent = '\ud83d\udca7 ' + (humidity !== null ? Math.round(humidity) + '%' : '--%');

  const cloudEl = wxEl('#wx-clouds');
  if (cloudEl) cloudEl.textContent = '\u2601\ufe0f ' + (clouds !== null ? Math.round(clouds) + '%' : '--%');

  const visEl = wxEl('#wx-visibility');
  if (visEl) visEl.textContent = '\ud83d\udc41\ufe0f --';

  if (pressure !== null) {
    const min = 980, max = 1050;
    const pct = Math.max(0, Math.min(100, ((pressure - min) / (max - min)) * 100));
    const fill   = wxEl('#baro-fill');
    const marker = wxEl('#baro-marker');
    const hint   = wxEl('#baro-hint');
    if (fill)   fill.style.width  = pct + '%';
    if (marker) marker.style.left = pct + '%';
    if (hint) {
      let baroDesc = '';
      if (pressure < 1000)      baroDesc = '\u26c8\ufe0f Stormy \u2014 fish deeper';
      else if (pressure < 1010) baroDesc = '\ud83c\udf27\ufe0f Low pressure \u2014 slow bite';
      else if (pressure < 1020) baroDesc = '\u26c5 Normal \u2014 average bite';
      else if (pressure < 1030) baroDesc = '\ud83c\udf24\ufe0f High pressure \u2014 fish edges';
      else                      baroDesc = '\u2600\ufe0f Very high \u2014 tough topwater';
      hint.textContent = pressure.toFixed(1) + ' mb \u2014 ' + baroDesc;
    }
  } else {
    const hint = wxEl('#baro-hint');
    if (hint) hint.textContent = '';
    const fill = wxEl('#baro-fill');
    if (fill) fill.style.width = '0%';
  }
}

// ── Main load ─────────────────────────────────────────────────────────────────
function loadAndDraw(loc, d) {
  const sb = htmlNode.querySelector('#scoreBar');
  if (!sb) return;

  const today = isToday(d);
  sb.innerHTML = '<span class="msg">Loading ' +
    (today ? 'today' : d.toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})) +
    '...</span>';

  if (today) {
    renderWeather(loc);
    loadFromPrometheus(loc, sb);
  } else {
    loadFromQueryEndpoint(loc, d, sb);
  }
}

// ── Load from Prometheus (today) ──────────────────────────────────────────────
function loadFromPrometheus(loc, sb) {
  Promise.all([
    pq('fishing_score_now{location="'+loc+'"}'),
    pq('fishing_tide_time_unix{location="'+loc+'"}'),
    pq('fishing_tide_height_ft{location="'+loc+'"}'),
    pq('fishing_solunar_major_start_unix{location="'+loc+'"}'),
    pq('fishing_solunar_major_end_unix{location="'+loc+'"}'),
    pq('fishing_solunar_minor_start_unix{location="'+loc+'"}'),
    pq('fishing_solunar_minor_end_unix{location="'+loc+'"}'),
    pq('fishing_sunrise_unix{location="'+loc+'"}'),
    pq('fishing_sunset_unix{location="'+loc+'"}'),
    pq('fishing_moonrise_unix{location="'+loc+'"}'),
    pq('fishing_moon_phase_pct{location="'+loc+'"}'),
  ]).then(R => {
    const score = R[0].length ? parseFloat(R[0][0].value[1]) : null;
    const moon  = R[10].length ? parseFloat(R[10][0].value[1]).toFixed(0) : '?';

    // Build tide events map: key = type_rank
    const tmap = {};
    R[1].forEach(r => {
      const k = r.metric.event_type + '_' + r.metric.event_rank;
      tmap[k] = tmap[k] || { type: r.metric.event_type };
      tmap[k].time = parseFloat(r.value[1]);
    });
    R[2].forEach(r => {
      const k = r.metric.event_type + '_' + r.metric.event_rank;
      tmap[k] = tmap[k] || { type: r.metric.event_type };
      tmap[k].height = parseFloat(r.value[1]);
    });
    const events = Object.values(tmap)
      .filter(e => e.time && e.height !== undefined)
      .map(e => {
        const dt = new Date(e.time * 1000);
        return { t: dt.getHours() + dt.getMinutes()/60, h: e.height, type: e.type };
      })
      .sort((a,b) => a.t - b.t);

    // Solunar windows — deduplicate major1/major2 if same value
    const maj1s = getByPeriod(R[3], 1), maj1e = getByPeriod(R[4], 1);
    const maj2s = getByPeriod(R[3], 2), maj2e = getByPeriod(R[4], 2);
    const min1s = getByPeriod(R[5], 1), min1e = getByPeriod(R[6], 1);
    const min2s = getByPeriod(R[5], 2), min2e = getByPeriod(R[6], 2);

    const majW = [];
    if (maj1s !== null && maj1e !== null) majW.push([toLocalHr(maj1s), toLocalHr(maj1e)]);
    // Only add major2 if it's actually different from major1
    if (maj2s !== null && maj2e !== null && Math.abs(maj2s - maj1s) > 60)
      majW.push([toLocalHr(maj2s), toLocalHr(maj2e)]);

    const minW = [];
    if (min1s !== null && min1e !== null) minW.push([toLocalHr(min1s), toLocalHr(min1e)]);
    if (min2s !== null && min2e !== null && Math.abs(min2s - min1s) > 60)
      minW.push([toLocalHr(min2s), toLocalHr(min2e)]);

    const sr = R[7].length ? toLocalHr(parseFloat(R[7][0].value[1])) : null;
    const ss = R[8].length ? toLocalHr(parseFloat(R[8][0].value[1])) : null;
    const mr = R[9].length ? toLocalHr(parseFloat(R[9][0].value[1])) : null;

    renderScoreBar(sb, score, moon, sr, ss, mr);
    renderImpactBar(events, majW, minW, sr, ss);
    drawChart(events, majW, minW, sr, ss, true);
  }).catch(e => {
    sb.innerHTML = '<span class="err">Error: '+e.message+'</span>';
  });
}

// ── Load from query endpoint (other dates) ────────────────────────────────────
function loadFromQueryEndpoint(loc, d, sb) {
  fetchDateData(loc, d).then(data => {
    if (!data || data.error) {
      sb.innerHTML = '<span class="err">Error: '+(data&&data.error ? data.error : 'fetch failed')+'</span>';
      return;
    }

    const score = data.fishing ? data.fishing.score : null;
    const moon  = data.moon ? data.moon.illumination.toFixed(0) : '?';
    const sr    = toLocalHr(data.sun       ? data.sun.sunrise_unix       : 0);
    const ss    = toLocalHr(data.sun       ? data.sun.sunset_unix        : 0);
    const mr    = toLocalHr(data.moon_events ? data.moon_events.moonrise_unix : 0);

    const events = (data.tides || [])
      .filter(e => e.time_unix && e.height_ft !== undefined)
      .map(e => {
        const dt = new Date(e.time_unix * 1000);
        return { t: dt.getHours() + dt.getMinutes()/60, h: e.height_ft, type: e.type };
      })
      .sort((a,b) => a.t - b.t);

    const sol  = data.solunar || {};
    const majW = [];
    if (sol.major1_start) majW.push([toLocalHr(sol.major1_start), toLocalHr(sol.major1_end)]);
    if (sol.major2_start && Math.abs(sol.major2_start - sol.major1_start) > 60)
      majW.push([toLocalHr(sol.major2_start), toLocalHr(sol.major2_end)]);

    const minW = [];
    if (sol.minor1_start) minW.push([toLocalHr(sol.minor1_start), toLocalHr(sol.minor1_end)]);
    if (sol.minor2_start && Math.abs(sol.minor2_start - sol.minor1_start) > 60)
      minW.push([toLocalHr(sol.minor2_start), toLocalHr(sol.minor2_end)]);

    renderWeatherFromQuery(data.weather || {});
    renderScoreBar(sb, score, moon, sr, ss, mr);
    renderImpactBar(events, majW, minW, sr, ss);
    drawChart(events, majW, minW, sr, ss, false);
  });
}

// ── Score bar ─────────────────────────────────────────────────────────────────
function renderScoreBar(sb, score, moon, sr, ss, mr) {
  const c = score>=8?'#2ed573':score>=6?'#ffd32a':score>=4?'#ffa502':'#ff4757';
  const l = score>=8?'EXCELLENT':score>=6?'GREAT':score>=4?'GOOD':score>=2?'FAIR':'SLOW';
  sb.innerHTML =
    '<span class="score-pill" style="background:'+c+'22;color:'+c+';border:1px solid '+c+'55;">' +
      (score!==null ? score.toFixed(1) : '?') + '/10 — ' + l +
    '</span>' +
    '<span class="score-stat">Moon '+moon+'%</span>' +
    '<span class="score-stat">☀️ '+fmtH(sr)+'</span>' +
    '<span class="score-stat">🌇 '+fmtH(ss)+'</span>' +
    '<span class="score-stat">🌙 '+fmtH(mr)+'</span>';
}

// ── Impact bar — summarizes key overlaps ──────────────────────────────────────
function renderImpactBar(events, majW, minW, sr, ss) {
  const bar = htmlNode.querySelector('#impact-bar');
  if (!bar) return;

  const items = [];

  // Tide events
  events.forEach(ev => {
    const lbl = ev.type === 'High' ? '🌊 High' : '〰️ Low';
    items.push('<span>' + lbl + ' tide ' + fmtH(ev.t) + ' (' + ev.h.toFixed(1) + 'ft)</span>');
  });

  // Solunar windows
  majW.forEach((w,i) => {
    if (w[0] !== null && w[1] !== null)
      items.push('<span style="color:#2ed573">🟢 Major ' + (i+1) + ': ' + fmtH(w[0]) + '–' + fmtH(w[1]) + '</span>');
  });
  minW.forEach((w,i) => {
    if (w[0] !== null && w[1] !== null)
      items.push('<span style="color:#ffd32a">🟡 Minor ' + (i+1) + ': ' + fmtH(w[0]) + '–' + fmtH(w[1]) + '</span>');
  });

  // Dawn/dusk
  if (sr) items.push('<span style="color:#ffd32a">☀️ Dawn ' + fmtH(sr) + '</span>');
  if (ss) items.push('<span style="color:#ff9f43">🌇 Dusk ' + fmtH(ss) + '</span>');

  bar.innerHTML = items.length ? items.join(' · ') : '<span>No data</span>';
}

// ── Tide curve interpolation ──────────────────────────────────────────────────
function buildCurve(events) {
  const pts = [], all = events.slice();
  if (!all.length) { for(let i=0;i<=96;i++) pts.push({x:i*0.25,y:0.7}); return pts; }
  if (all[0].t > 0) all.unshift({t:all[all.length-1].t-24, h:all[all.length-1].h, type:all[all.length-1].type});
  if (all[all.length-1].t < 24) all.push({t:events[0].t+24, h:events[0].h, type:events[0].type});
  for (let i=0;i<=96;i++) {
    const hr=i*0.25; let val=0, tw=0;
    all.forEach(ev => { const d=Math.abs(hr-ev.t), w=1/(d*d+0.08); val+=w*ev.h; tw+=w; });
    pts.push({x:hr, y:val/tw});
  }
  return pts;
}

// ── Chart ─────────────────────────────────────────────────────────────────────
function drawChart(events, majW, minW, sr, ss, showNow) {
  const curve  = buildCurve(events);
  const labels = curve.map(p=>p.x);
  const data   = curve.map(p=>p.y);
  const now    = new Date().getHours() + new Date().getMinutes()/60;
  const night1 = labels.map(h=>(sr&&h<=sr)?0.45:0);
  const night2 = labels.map(h=>(ss&&h>=ss)?0.45:0);
  const canvas = htmlNode.querySelector('#tideChart');
  if (!canvas) return;

  const majData = (()=>{ const d=[]; for(let i=0;i<=96;i++){const h=i*0.25; d.push(majW.some(w=>h>=w[0]&&h<=w[1])?0.45:0);} return d; })();
  const minData = (()=>{ const d=[]; for(let i=0;i<=96;i++){const h=i*0.25; d.push(minW.some(w=>h>=w[0]&&h<=w[1])?0.45:0);} return d; })();

  function doRender(ChartJS) {
    const existing = ChartJS.getChart(canvas);
    if (existing) existing.destroy();

    new ChartJS(canvas, {
      type:'line',
      data:{ labels, datasets:[
        { type:'bar', label:'Night',         backgroundColor:'rgba(0,5,30,0.5)',       data:night1, barPercentage:1.02, categoryPercentage:1.02, yAxisID:'y', order:6 },
        { type:'bar', label:'Night2',        backgroundColor:'rgba(0,5,30,0.5)',       data:night2, barPercentage:1.02, categoryPercentage:1.02, yAxisID:'y', order:6 },
        { type:'bar', label:'Major solunar', backgroundColor:'rgba(46,213,115,0.22)',  data:majData, barPercentage:1.02, categoryPercentage:1.02, yAxisID:'y', order:5 },
        { type:'bar', label:'Minor solunar', backgroundColor:'rgba(255,195,0,0.18)',   data:minData, barPercentage:1.02, categoryPercentage:1.02, yAxisID:'y', order:5 },
        { type:'line', label:'Tide height (ft)', data, borderColor:'#1e90ff',
          backgroundColor:'rgba(30,144,255,0.15)', fill:true, tension:0.42,
          pointRadius:0, borderWidth:2.5, order:2, yAxisID:'y' }
      ]},
      options:{
        responsive:true, maintainAspectRatio:false, animation:{duration:500},
        plugins:{
          legend:{ display:false },
          tooltip:{
            filter: i => i.dataset.label === 'Tide height (ft)',
            backgroundColor:'#0d1f3c', titleColor:'#7eb8ff', bodyColor:'#fff',
            borderColor:'#1e90ff', borderWidth:1,
            callbacks:{
              title: items => {
                if (!items.length) return '';
                const h=items[0].parsed.x, hr=Math.floor(h), mn=Math.round((h%1)*60);
                return (hr%12||12)+':'+(mn<10?'0':'')+mn+(hr<12?'am':'pm');
              },
              label: i => ' '+i.parsed.y.toFixed(2)+' ft'
            }
          }
        },
        scales:{
          x:{ type:'linear', min:0, max:24,
              ticks:{ stepSize:3, color:'#3d5a7a', font:{size:10},
                      callback: v => v===0?'12am':v<12?v+'am':v===12?'12pm':(v-12)+'pm' },
              grid:{ color:'rgba(255,255,255,0.04)' },
              border:{ color:'rgba(255,255,255,0.08)' } },
          y:{ min:-0.4, max:2.6,
              ticks:{ color:'#3d5a7a', font:{size:10}, stepSize:0.5, callback: v => v.toFixed(1)+'ft' },
              grid:{ color:'rgba(255,255,255,0.05)' },
              border:{ color:'rgba(255,255,255,0.08)' } }
        }
      },
      plugins:[{
        id:'custom',
        afterDraw(ch) {
          const ctx=ch.ctx, xS=ch.scales.x, yS=ch.scales.y;
          // NOW line
          if (showNow) {
            const nx=xS.getPixelForValue(now);
            ctx.save();
            ctx.strokeStyle='#ff6b6b'; ctx.lineWidth=1.5; ctx.setLineDash([4,4]);
            ctx.beginPath(); ctx.moveTo(nx,yS.top); ctx.lineTo(nx,yS.bottom); ctx.stroke();
            ctx.setLineDash([]);
            ctx.fillStyle='#ff6b6b'; ctx.font='bold 9px Georgia'; ctx.textAlign='center';
            ctx.fillText('NOW',nx,yS.top-3);
            ctx.restore();
          }
          // Sunrise / sunset lines
          [[sr,'#ffd32a','sunrise'],[ss,'#ff9f43','sunset']].forEach(([h,col,lbl])=>{
            if (!h) return;
            const px=xS.getPixelForValue(h);
            ctx.save();
            ctx.strokeStyle=col; ctx.lineWidth=1; ctx.setLineDash([2,4]);
            ctx.beginPath(); ctx.moveTo(px,yS.top); ctx.lineTo(px,yS.bottom); ctx.stroke();
            ctx.setLineDash([]);
            ctx.fillStyle=col; ctx.font='9px Georgia'; ctx.textAlign='center';
            ctx.fillText(lbl,px,yS.bottom+13);
            ctx.restore();
          });
          // Tide event dots + labels
          events.forEach(ev=>{
            const ex=xS.getPixelForValue(ev.t), ey=yS.getPixelForValue(ev.h), isH=ev.type==='High';
            ctx.save();
            ctx.beginPath(); ctx.arc(ex,ey,5,0,Math.PI*2);
            ctx.fillStyle=isH?'#1e90ff':'#48dbfb'; ctx.strokeStyle='#0a1628'; ctx.lineWidth=1.5;
            ctx.fill(); ctx.stroke();
            ctx.fillStyle='#b0c8e8'; ctx.font='bold 9px Georgia'; ctx.textAlign='center';
            ctx.fillText((isH?'H':'L')+' '+ev.h.toFixed(1)+'ft', ex, isH?ey-11:ey+18);
            ctx.restore();
          });
        }
      }]
    });
  }

  if (typeof Chart !== 'undefined') {
    doRender(Chart);
  } else {
    fetch('https://cdnjs.cloudflare.com/ajax/libs/Chart.js/4.4.1/chart.umd.js')
      .then(r => r.text())
      .then(src => {
        const mod = new Function('exports','module', src + '; return module.exports;');
        const exp = {}, m = {exports:{}};
        mod(exp, m);
        doRender(m.exports.Chart || m.exports);
      })
      .catch(e => {
        const sb = htmlNode.querySelector('#scoreBar');
        if (sb) sb.innerHTML += '<span class="err"> Chart.js load failed: '+e.message+'</span>';
      });
  }
}

// ── Boot ──────────────────────────────────────────────────────────────────────
init();

options.css:
* { box-sizing:border-box; margin:0; padding:0; }
body { background:transparent; font-family:Georgia,serif; color:#cde; }

.wrap {
  background:#0a1628;
  border-radius:10px;
  padding:14px;
  display:flex;
  flex-direction:column;
  gap:8px;
}

/* ── Search row ── */
.search-row {
  display:flex;
  align-items:center;
  gap:10px;
  flex-wrap:wrap;
}
.search-box-wrap {
  position:relative;
  flex:1;
  min-width:200px;
}
.station-input {
  width:100%;
  background:#0d1f3c;
  border:1px solid rgba(30,144,255,0.4);
  border-radius:20px;
  color:#7eb8ff;
  font-size:13px;
  padding:6px 16px;
  outline:none;
  font-family:Georgia,serif;
}
.station-input::placeholder { color:#3d5a7a; }
.station-input:focus { border-color:#1e90ff; box-shadow:0 0 0 2px rgba(30,144,255,0.15); }

.search-dropdown {
  position:absolute;
  top:calc(100% + 2px);
  left:0; right:0;
  z-index:9999;
  background:#111e35;
  border:1px solid rgba(30,144,255,0.35);
  border-radius:10px;
  max-height:220px;
  overflow-y:auto;
  box-shadow:0 8px 24px rgba(0,0,0,0.6);
}
.search-dropdown.hidden { display:none; }
.dd-item {
  padding:8px 14px;
  cursor:pointer;
  border-bottom:1px solid rgba(255,255,255,0.05);
  transition:background 0.15s;
}
.dd-item:last-child { border-bottom:none; }
.dd-item:hover { background:rgba(30,144,255,0.12); }
.dd-name { font-size:12px; color:#b0c8e8; }
.dd-meta { font-size:10px; color:#3d5a7a; margin-top:1px; }
.dd-empty { padding:10px 14px; font-size:11px; color:#3d5a7a; }

/* ── Station tag ── */
.station-tag {
  display:flex;
  align-items:center;
  gap:8px;
  background:rgba(30,144,255,0.1);
  border:1px solid rgba(30,144,255,0.3);
  border-radius:20px;
  padding:4px 12px;
  font-size:12px;
  color:#7eb8ff;
  white-space:nowrap;
}
.tag-id {
  background:rgba(30,144,255,0.2);
  border-radius:10px;
  padding:1px 8px;
  font-size:10px;
  color:#48dbfb;
}

/* ── Date row ── */
.date-row {
  display:flex;
  align-items:center;
  gap:8px;
  flex-wrap:wrap;
}
.nav-btn {
  background:rgba(255,255,255,0.07);
  color:#7eb8ff;
  border:1px solid rgba(30,144,255,0.3);
  border-radius:8px;
  padding:4px 12px;
  font-size:14px;
  cursor:pointer;
  transition:all 0.2s;
  font-family:Georgia,serif;
}
.nav-btn:hover { background:rgba(30,144,255,0.2); border-color:#1e90ff; color:#fff; }
.today-btn { font-size:11px; padding:4px 10px; color:#48dbfb; border-color:rgba(72,219,251,0.4); }
.today-btn:hover { background:rgba(72,219,251,0.15); border-color:#48dbfb; }
#datePicker {
  background:#0d1f3c;
  border:1px solid rgba(30,144,255,0.4);
  border-radius:8px;
  color:#7eb8ff;
  font-size:13px;
  padding:4px 10px;
  cursor:pointer;
  outline:none;
  font-family:Georgia,serif;
}
#datePicker::-webkit-calendar-picker-indicator {
  filter:invert(0.6) sepia(1) saturate(5) hue-rotate(175deg);
  cursor:pointer;
}

/* ── Weather strip ── */
.wx-strip {
  background:rgba(30,144,255,0.06);
  border:1px solid rgba(30,144,255,0.12);
  border-radius:8px;
  padding:8px 12px;
  display:flex;
  flex-direction:column;
  gap:5px;
}
.wx-strip-main {
  display:flex;
  align-items:baseline;
  gap:10px;
  flex-wrap:wrap;
}
.wx-big-temp { font-size:28px; font-weight:bold; color:#fff; line-height:1; }
.wx-feels    { font-size:12px; color:#5a7fa0; }
.wx-desc     { font-size:13px; color:#b0c8e8; }
.wx-strip-stats {
  display:flex;
  gap:10px;
  flex-wrap:wrap;
  align-items:center;
}
.wx-stat    { font-size:11px; color:#7eb8ff; white-space:nowrap; }
.trend-stat { font-size:14px; font-weight:bold; }

/* ── Barometer bar ── */
.baro-row {
  display:flex;
  align-items:center;
  gap:8px;
  padding:0 2px;
}
.baro-label-left,.baro-label-right { font-size:9px; color:#3d5a7a; white-space:nowrap; }
.baro-track {
  flex:1;
  position:relative;
  height:6px;
  background:linear-gradient(to right,#1a3a8f,#1e90ff,#48dbfb,#2ed573,#ffd32a,#ff6b6b);
  border-radius:3px;
}
.baro-fill {
  position:absolute;
  left:0; top:0; bottom:0;
  background:rgba(0,0,0,0.45);
  border-radius:3px 0 0 3px;
  transition:width 0.5s;
}
.baro-marker {
  position:absolute;
  top:-3px;
  width:12px; height:12px;
  background:#fff;
  border:2px solid #1e90ff;
  border-radius:50%;
  transform:translateX(-50%);
  transition:left 0.5s;
}
.baro-hint { font-size:10px; color:#5a7fa0; white-space:nowrap; flex-shrink:0; }

/* ── Score / status bar ── */
.score-bar {
  background:rgba(255,255,255,0.04);
  border-radius:8px;
  padding:7px 12px;
  font-size:12px;
  color:#7eb8ff;
  display:flex;
  align-items:center;
  gap:8px;
  flex-wrap:wrap;
  min-height:32px;
}
.score-bar .msg { color:#3d5a7a; font-style:italic; }
.score-bar .err { color:#ff4757; }

/* ── Chart ── */
.chart-wrap { position:relative; height:160px; }

/* ── Tide table ── */
.tide-table {
  width:100%;
  border-collapse:collapse;
  font-size:12px;
  margin-top:4px;
}
.tide-table th {
  color:#3d5a7a;
  font-size:10px;
  font-weight:normal;
  padding:2px 6px;
  border-bottom:1px solid rgba(255,255,255,0.07);
  text-transform:uppercase;
  letter-spacing:.05em;
}
.tide-table td { padding:5px 6px; }
.tide-table tr:hover td { background:rgba(30,144,255,0.06); }

/* ── Legend ── */
.legend {
  display:flex;
  gap:14px;
  font-size:10px;
  color:#3d5a7a;
  flex-wrap:wrap;
  align-items:center;
}
.ldot {
  display:inline-block;
  width:14px; height:14px;
  border-radius:3px;
  vertical-align:middle;
  margin-right:4px;
}

options.onRender:
const FISH_HOST = 'http://' + window.location.hostname + ':9879';

let activeStation = null;
let activeDate    = new Date();
let searchTimer   = null;

// ── Date helpers ──────────────────────────────────────────────────────────────
function toInputVal(d) {
  return d.getFullYear() + '-' +
    String(d.getMonth()+1).padStart(2,'0') + '-' +
    String(d.getDate()).padStart(2,'0');
}
function isToday(d) {
  const t = new Date();
  return d.getFullYear()===t.getFullYear() && d.getMonth()===t.getMonth() && d.getDate()===t.getDate();
}
function offsetDate(d, n) { const nd=new Date(d); nd.setDate(nd.getDate()+n); return nd; }
function fmtHr(h) {
  if (h===null||h===undefined) return '--';
  const hh=Math.floor(h)%24, mm=Math.round((h%1)*60);
  return (hh%12||12)+':'+(mm<10?'0':'')+mm+(hh<12?'am':'pm');
}

// ── Sunrise / sunset (standard almanac approximation) ────────────────────────
function sunTimes(lat, lng, date) {
  const toRad = d => d*Math.PI/180, toDeg = r => r*180/Math.PI;
  const start = new Date(date.getFullYear(),0,0);
  const D = Math.round((date-start)/86400000);
  const zenith=90.833, lngHour=lng/15;
  function calc(t, rising) {
    const M=(0.9856*t)-3.289;
    let L=M+1.916*Math.sin(toRad(M))+0.020*Math.sin(toRad(2*M))+282.634;
    L=((L%360)+360)%360;
    let RA=toDeg(Math.atan(0.91764*Math.tan(toRad(L))));
    RA=((RA%360)+360)%360;
    const Lq=Math.floor(L/90)*90, RAq=Math.floor(RA/90)*90;
    RA=(RA+Lq-RAq)/15;
    const sinDec=0.39782*Math.sin(toRad(L)), cosDec=Math.cos(Math.asin(sinDec));
    const cosH=(Math.cos(toRad(zenith))-sinDec*Math.sin(toRad(lat)))/(cosDec*Math.cos(toRad(lat)));
    if (cosH>1||cosH<-1) return null;
    const H=(rising?360-toDeg(Math.acos(cosH)):toDeg(Math.acos(cosH)))/15;
    const T=H+RA-0.06571*t-6.622;
    const UT=((T-lngHour)%24+24)%24;
    const off=-new Date().getTimezoneOffset()/60;
    return ((UT+off)%24+24)%24;
  }
  return [calc(D+(6-lngHour)/24,true), calc(D+(18-lngHour)/24,false)];
}

// ── IDW tide curve (same algorithm as existing tide panel) ───────────────────
function buildCurve(events) {
  const pts=[], all=events.slice();
  if (!all.length) { for(let i=0;i<=96;i++) pts.push({x:i*0.25,y:0.7}); return pts; }
  if (all[0].t>0) all.unshift({t:all[all.length-1].t-24,h:all[all.length-1].h,type:all[all.length-1].type});
  if (all[all.length-1].t<24) all.push({t:events[0].t+24,h:events[0].h,type:events[0].type});
  for (let i=0;i<=96;i++) {
    const hr=i*0.25; let val=0,tw=0;
    all.forEach(ev=>{ const dd=Math.abs(hr-ev.t),w=1/(dd*dd+0.08); val+=w*ev.h; tw+=w; });
    pts.push({x:hr,y:val/tw});
  }
  return pts;
}

// ── Chart.js rendering ───────────────────────────────────────────────────────
function drawChart(events, sr, ss) {
  const curve=buildCurve(events);
  const labels=curve.map(p=>p.x), data=curve.map(p=>p.y);
  const now=new Date().getHours()+new Date().getMinutes()/60;
  const night1=labels.map(h=>(sr!==null&&h<=sr)?0.45:0);
  const night2=labels.map(h=>(ss!==null&&h>=ss)?0.45:0);
  const canvas=htmlNode.querySelector('#tideChart');
  if (!canvas) return;

  function doRender(ChartJS) {
    const ex=ChartJS.getChart(canvas); if(ex) ex.destroy();
    new ChartJS(canvas,{
      type:'line',
      data:{labels,datasets:[
        {type:'bar',label:'Night', backgroundColor:'rgba(0,5,30,0.5)', data:night1,barPercentage:1.02,categoryPercentage:1.02,yAxisID:'y',order:6},
        {type:'bar',label:'Night2',backgroundColor:'rgba(0,5,30,0.5)', data:night2,barPercentage:1.02,categoryPercentage:1.02,yAxisID:'y',order:6},
        {type:'line',label:'Tide height (ft)',data,borderColor:'#1e90ff',
         backgroundColor:'rgba(30,144,255,0.15)',fill:true,tension:0.42,
         pointRadius:0,borderWidth:2.5,order:2,yAxisID:'y'},
      ]},
      options:{
        responsive:true,maintainAspectRatio:false,animation:{duration:400},
        plugins:{
          legend:{display:false},
          tooltip:{callbacks:{label:ctx=>(ctx.dataset.label||'')+': '+ctx.parsed.y.toFixed(2)+' ft'}},
        },
        scales:{
          x:{type:'linear',min:0,max:24,
             ticks:{stepSize:2,callback:h=>{const hh=h%12||12;return hh+(h<12?'a':'p');},color:'#5a7fa0',font:{size:10}},
             grid:{color:'rgba(255,255,255,0.05)'},border:{color:'rgba(255,255,255,0.1)'}},
          y:{ticks:{callback:v=>v.toFixed(1)+'ft',color:'#5a7fa0',font:{size:10}},
             grid:{color:'rgba(255,255,255,0.05)'},border:{color:'rgba(255,255,255,0.1)'}},
        },
      },
      plugins:[
        {id:'nowLine',afterDraw(chart){
          if(!isToday(activeDate)) return;
          const {ctx,chartArea:{top,bottom},scales:{x}}=chart;
          const xPx=x.getPixelForValue(now);
          ctx.save(); ctx.setLineDash([4,3]); ctx.strokeStyle='#ff6b6b'; ctx.lineWidth=1.5;
          ctx.beginPath(); ctx.moveTo(xPx,top); ctx.lineTo(xPx,bottom); ctx.stroke(); ctx.restore();
        }},
        {id:'tideMarkers',afterDatasetsDraw(chart){
          const {ctx,scales:{x,y}}=chart;
          events.forEach(ev=>{
            const isH=ev.type==='H';
            const ex=x.getPixelForValue(ev.t), ey=y.getPixelForValue(ev.h);
            ctx.save();
            ctx.beginPath(); ctx.arc(ex,ey,5,0,Math.PI*2);
            ctx.fillStyle=isH?'#1e90ff':'#48dbfb'; ctx.strokeStyle='#0a1628'; ctx.lineWidth=1.5;
            ctx.fill(); ctx.stroke();
            ctx.fillStyle='#b0c8e8'; ctx.font='bold 9px Georgia'; ctx.textAlign='center';
            ctx.fillText((isH?'H':'L')+' '+ev.h.toFixed(1)+'ft',ex,isH?ey-11:ey+18);
            ctx.restore();
          });
        }},
      ],
    });
  }

  if (typeof Chart!=='undefined') {
    doRender(Chart);
  } else {
    fetch('https://cdnjs.cloudflare.com/ajax/libs/Chart.js/4.4.1/chart.umd.js')
      .then(r=>r.text())
      .then(src=>{
        const mod=new Function('exports','module',src+'; return module.exports;');
        const exp={},m={exports:{}};
        mod(exp,m);
        doRender(m.exports.Chart||m.exports);
      })
      .catch(e=>{
        const sb=htmlNode.querySelector('#scoreBar');
        if(sb) sb.innerHTML='<span class="err">Chart.js load failed: '+e.message+'</span>';
      });
  }
}

// ── Tide events table ────────────────────────────────────────────────────────
function renderTable(events) {
  const tbl=htmlNode.querySelector('#tideTable');
  if (!tbl||!events.length) { if(tbl) tbl.innerHTML=''; return; }
  const highs=events.filter(e=>e.type==='H').map(e=>e.h);
  const lows =events.filter(e=>e.type==='L').map(e=>e.h);
  const range=highs.length&&lows.length
    ? ' &nbsp;·&nbsp; Range: <strong style="color:#7eb8ff">'+(Math.max(...highs)-Math.min(...lows)).toFixed(2)+' ft</strong>'
    : '';
  const rows=events.map(ev=>{
    const isH=ev.type==='H';
    const hh=Math.floor(ev.t),mm=Math.round((ev.t%1)*60);
    const ampm=hh>=12?'PM':'AM', h12=hh===0?12:hh>12?hh-12:hh;
    const timeStr=h12+':'+(mm<10?'0':'')+mm+' '+ampm;
    const col=ev.h<0?'#ff4757':isH?'#1e90ff':'#48dbfb';
    return `<tr>
      <td style="color:${isH?'#1e90ff':'#48dbfb'};font-size:16px;padding:4px 8px;">${isH?'▲':'▼'}</td>
      <td style="padding:4px 8px;"><strong>${timeStr}</strong></td>
      <td style="padding:4px 8px;color:${isH?'#1e90ff':'#48dbfb'}">${isH?'High':'Low'} Tide</td>
      <td style="padding:4px 8px;text-align:right;"><strong style="color:${col}">${ev.h.toFixed(2)} ft</strong></td>
    </tr>`;
  }).join('');
  tbl.innerHTML=`
    <div style="font-size:10px;color:#3d5a7a;margin:4px 0 5px;padding:0 2px;">
      Heights in ft · MLLW datum · Local station time${range}
    </div>
    <table class="tide-table">
      <thead><tr>
        <th></th><th>Time</th><th>Event</th><th style="text-align:right">Height</th>
      </tr></thead>
      <tbody>${rows}</tbody>
    </table>`;
}

// ── Compass direction from degrees ───────────────────────────────────────────
function degToCompass(deg) {
  if (deg===null||deg===undefined) return '';
  const dirs=['N','NNE','NE','ENE','E','ESE','SE','SSE','S','SSW','SW','WSW','W','WNW','NW','NNW'];
  return dirs[Math.round(deg/22.5)%16];
}

// ── Weather strip ─────────────────────────────────────────────────────────────
async function loadWeather(lat, lng, date) {
  const strip  = htmlNode.querySelector('#wxStrip');
  const baroR  = htmlNode.querySelector('#baroRow');
  if (!strip) return;

  // Clear while loading
  const el = id => htmlNode.querySelector(id);
  if (el('#wx-temp')) el('#wx-temp').textContent = '--';
  if (el('#wx-desc')) el('#wx-desc').textContent = 'Loading weather…';

  try {
    const r = await fetch(
      FISH_HOST+'/api/weather?lat='+lat+'&lng='+lng+'&date='+toInputVal(date)
    );
    const wx = await r.json();
    if (wx.error) {
      if (el('#wx-desc')) el('#wx-desc').textContent = wx.error;
      strip.style.display = '';
      return;
    }

    // Temp
    if (el('#wx-temp')) el('#wx-temp').textContent = wx.temp_f!==null ? Math.round(wx.temp_f)+'°F' : '--';
    if (el('#wx-feels')) el('#wx-feels').textContent = wx.feels_f!==null ? 'Feels '+Math.round(wx.feels_f)+'°F' : '';
    if (el('#wx-desc'))  el('#wx-desc').textContent  = wx.description || '';

    // Pressure
    if (el('#wx-pressure')) el('#wx-pressure').textContent = wx.pressure_mb!==null ? wx.pressure_mb.toFixed(1)+' mb' : '';

    // Trend — no historical data for arbitrary stations, omit trend arrow
    if (el('#wx-trend')) el('#wx-trend').textContent = '';

    // Wind
    const wSpd = wx.wind_mph!==null ? wx.wind_mph.toFixed(0)+' mph' : null;
    const wDir = wx.wind_deg!==null ? degToCompass(wx.wind_deg) : '';
    if (el('#wx-wind')) el('#wx-wind').textContent = wSpd ? wSpd+' '+wDir : '-- mph';

    if (el('#wx-precip'))   el('#wx-precip').textContent   = '🌧️ '+(wx.precip_pct!==null ? wx.precip_pct+'%' : '--%');
    if (el('#wx-humidity')) el('#wx-humidity').textContent = '💧 '+(wx.humidity!==null   ? wx.humidity+'%'  : '--%');
    if (el('#wx-clouds'))   el('#wx-clouds').textContent   = '☁️ '+(wx.cloud_pct!==null  ? wx.cloud_pct+'%' : '--%');
    if (el('#wx-visibility')) {
      el('#wx-visibility').textContent = wx.vis_mi!==null ? '👁️ '+wx.vis_mi+' mi' : '';
    }

    strip.style.display = '';

    // Barometer
    if (wx.pressure_mb!==null && baroR) {
      const min=980, max=1050;
      const pct=Math.max(0,Math.min(100,((wx.pressure_mb-min)/(max-min))*100));
      const fill  =el('#baro-fill');
      const marker=el('#baro-marker');
      const hint  =el('#baro-hint');
      if (fill)   fill.style.width   = pct+'%';
      if (marker) marker.style.left  = pct+'%';
      if (hint) {
        let desc='';
        if (wx.pressure_mb<1000)      desc='⛈️ Stormy — fish deeper';
        else if (wx.pressure_mb<1010) desc='🌧️ Low pressure — slow bite';
        else if (wx.pressure_mb<1020) desc='⛅ Normal — average bite';
        else if (wx.pressure_mb<1030) desc='🌤️ High pressure — fish edges';
        else                          desc='☀️ Very high — tough topwater';
        hint.textContent = wx.pressure_mb.toFixed(1)+' mb — '+desc;
      }
      baroR.style.display = '';
    } else if (baroR) {
      baroR.style.display = 'none';
    }
  } catch(e) {
    if (el('#wx-desc')) el('#wx-desc').textContent = 'Weather unavailable';
    strip.style.display = '';
  }
}

// ── Fetch tides from Flask API ───────────────────────────────────────────────
async function loadTides(stationId, date) {
  const sb=htmlNode.querySelector('#scoreBar');
  const cw=htmlNode.querySelector('#chartWrap');
  const lg=htmlNode.querySelector('#legendRow');
  const tt=htmlNode.querySelector('#tideTable');
  if(sb) sb.innerHTML='<span class="msg">Loading tide predictions…</span>';
  if(cw) cw.style.display='none';
  if(lg) lg.style.display='none';
  if(tt) tt.innerHTML='';

  try {
    const r=await fetch(FISH_HOST+'/api/tides/station?id='+stationId+'&date='+toInputVal(date));
    const data=await r.json();
    if(data.error){ if(sb) sb.innerHTML='<span class="err">⚠ '+data.error+'</span>'; return; }

    const preds=data.predictions||[];
    if(!preds.length){ if(sb) sb.innerHTML='<span class="msg">No predictions available for this date.</span>'; return; }

    const events=preds.map(p=>{
      const [,hhmm]=p.t.split(' '), [hh,mm]=hhmm.split(':').map(Number);
      return {t:hh+mm/60, h:parseFloat(p.v), type:p.type};
    }).sort((a,b)=>a.t-b.t);

    let sr=null, ss=null;
    if(activeStation&&activeStation.lat&&activeStation.lng)
      [sr,ss]=sunTimes(parseFloat(activeStation.lat),parseFloat(activeStation.lng),date);

    const highs=events.filter(e=>e.type==='H');
    const lows =events.filter(e=>e.type==='L');
    const maxH=highs.length?Math.max(...highs.map(e=>e.h)).toFixed(2):'--';
    const minL=lows.length ?Math.min(...lows.map(e=>e.h)).toFixed(2):'--';
    const dlbl=date.toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric',year:'numeric'});
    if(sb) sb.innerHTML=
      '<span style="color:#48dbfb;font-weight:bold">'+dlbl+'</span>'+
      ' &nbsp;·&nbsp; <span style="color:#1e90ff">▲ High: '+maxH+' ft</span>'+
      ' &nbsp;·&nbsp; <span style="color:#48dbfb">▼ Low: '+minL+' ft</span>'+
      (sr!==null&&ss!==null?' &nbsp;·&nbsp; <span style="color:#ffd32a">🌅 '+fmtHr(sr)+' – '+fmtHr(ss)+'</span>':'');

    if(cw) cw.style.display='';
    if(lg) lg.style.display='';
    drawChart(events,sr,ss);
    renderTable(events);
  } catch(e) {
    if(sb) sb.innerHTML='<span class="err">⚠ Failed to fetch tide data: '+e.message+'</span>';
  }
}

// ── Station search ───────────────────────────────────────────────────────────
async function doSearch(q) {
  const dd=htmlNode.querySelector('#searchDropdown');
  if(!dd) return;
  try {
    const r=await fetch(FISH_HOST+'/api/stations/search?q='+encodeURIComponent(q));
    const results=await r.json();
    if(results.error||!Array.isArray(results)){ dd.classList.add('hidden'); return; }
    showDropdown(results,dd);
  } catch(e){ dd.classList.add('hidden'); }
}

function showDropdown(stations, dd) {
  if(!stations.length){
    dd.innerHTML='<div class="dd-empty">No stations found</div>';
  } else {
    dd.innerHTML=stations.map(s=>{
      const label=s.name+(s.state?', '+s.state:'');
      const coord=(s.lat&&s.lng)?parseFloat(s.lat).toFixed(2)+'°N '+Math.abs(parseFloat(s.lng)).toFixed(2)+'°W':'';
      return '<div class="dd-item" data-id="'+s.id+'" data-name="'+label+'" data-lat="'+(s.lat||'')+'" data-lng="'+(s.lng||'')+'">'+
             '<div class="dd-name">'+label+'</div>'+
             '<div class="dd-meta">ID: '+s.id+(coord?' · '+coord:'')+'</div>'+
             '</div>';
    }).join('');
    dd.querySelectorAll('.dd-item').forEach(el=>{
      el.addEventListener('click',()=>{
        const sel={id:el.dataset.id,name:el.dataset.name,lat:el.dataset.lat||null,lng:el.dataset.lng||null};
        const si=htmlNode.querySelector('#stationSearch');
        if(si) si.value=sel.name;
        dd.classList.add('hidden');
        selectStation(sel);
      });
      el.addEventListener('mouseenter',()=>el.style.background='rgba(30,144,255,0.12)');
      el.addEventListener('mouseleave',()=>el.style.background='');
    });
  }
  dd.classList.remove('hidden');
}

function selectStation(station) {
  activeStation=station;
  const tag=htmlNode.querySelector('#stationTag');
  const tn =htmlNode.querySelector('#tagName');
  const ti =htmlNode.querySelector('#tagId');
  if(tag) tag.style.display='';
  if(tn)  tn.textContent=station.name;
  if(ti)  ti.textContent='ID '+station.id;
  loadTides(station.id,activeDate);
  if(station.lat&&station.lng)
    loadWeather(station.lat,station.lng,activeDate);
}

// ── Init ─────────────────────────────────────────────────────────────────────
function init() {
  const si=htmlNode.querySelector('#stationSearch');
  const dd=htmlNode.querySelector('#searchDropdown');
  const pk=htmlNode.querySelector('#datePicker');
  const bp=htmlNode.querySelector('#btn-prev');
  const bn=htmlNode.querySelector('#btn-next');
  const bt=htmlNode.querySelector('#btn-today');
  if(!si){ setTimeout(init,100); return; }

  pk.value=toInputVal(activeDate);

  si.addEventListener('input',()=>{
    clearTimeout(searchTimer);
    const q=si.value.trim();
    if(q.length<2){ if(dd) dd.classList.add('hidden'); return; }
    searchTimer=setTimeout(()=>doSearch(q),300);
  });

  document.addEventListener('click',e=>{
    if(dd&&e.target&&!si.contains(e.target)&&!dd.contains(e.target))
      dd.classList.add('hidden');
  });

  function changeDate(newDate) {
    activeDate=newDate;
    pk.value=toInputVal(newDate);
    if(activeStation) {
      loadTides(activeStation.id,newDate);
      if(activeStation.lat&&activeStation.lng)
        loadWeather(activeStation.lat,activeStation.lng,newDate);
    }
  }

  pk.addEventListener('change',()=>{
    const parts=pk.value.split('-');
    changeDate(new Date(parseInt(parts[0]),parseInt(parts[1])-1,parseInt(parts[2])));
  });
  bp.addEventListener('click',()=>changeDate(offsetDate(activeDate,-1)));
  bn.addEventListener('click',()=>changeDate(offsetDate(activeDate,1)));
  bt.addEventListener('click',()=>changeDate(new Date()));
}

init();
